create table admin (id bigint not null, primary key (id));
create table admission_cycle (active boolean unique, application_deadline date not null, evaluation_deadline date not null, id bigint generated by default as identity, name varchar(255) not null unique, primary key (id));
create table applicant (id bigint not null, primary key (id));
create table application (applicant_id bigint not null, cycle_id bigint not null, desired_field_id bigint, id bigint generated by default as identity, submitted_at timestamp(6), citizenship varchar(255), email varchar(255) not null, first_name varchar(255) not null, last_name varchar(255) not null, phone_number varchar(255), status varchar(255) not null check ((status in ('DRAFT','SUBMITTED','SCREENED_OUT','UNDER_REVIEW','ADMITTED','REJECTED'))), primary key (id));
create table application_preferred_professors (application_id bigint not null, professor_id bigint not null, primary key (application_id, professor_id));
create table document (application_id bigint not null, id bigint generated by default as identity, size bigint not null, uploaded_at timestamp(6) not null, bytes bytea not null, content_type varchar(255) not null, file_name varchar(255) not null, type varchar(255) not null check ((type in ('CV','DIPLOMA','GRADE_AUDIT'))), primary key (id), constraint uk_document_application_type unique (application_id, type));
create table evaluation (application_id bigint not null, assigned_at timestamp(6) not null, id bigint generated by default as identity, notified_at timestamp(6), professor_id bigint not null, submitted_at timestamp(6), version bigint default 0 not null, comments varchar(2000), recommendation varchar(255) check ((recommendation in ('DO_NOT_RECOMMEND','RECOMMEND_NO_SUPERVISION','RECOMMEND_NO_FUNDING','RECOMMEND_WITH_FUNDING'))), primary key (id), constraint uk_evaluation_application_professor unique (application_id, professor_id));
create table professor (id bigint not null, primary key (id));
create table professor_research_fields (professor_id bigint not null, research_field_id bigint not null, primary key (professor_id, research_field_id));
create table research_field (id bigint generated by default as identity, name varchar(255) not null unique, primary key (id));
create table users (id bigint generated by default as identity, email varchar(255) not null unique, name varchar(255) not null, password_hash varchar(255), primary key (id));
alter table if exists admin add constraint FKqer4e53tfnl17s22ior7fcsv8 foreign key (id) references users;
alter table if exists applicant add constraint FK7wlrg5kyi62w9idppuwlsd395 foreign key (id) references users;
