alter table if exists application_preferred_professors add constraint FKnjorohaqnmky99yi88hkydlic foreign key (application_id) references application;
alter table if exists document add constraint FK44725n9linud4cn2b1rsmavia foreign key (application_id) references application;
alter table if exists evaluation add constraint FK8kmneeb146rbmsvm1jkhoy1s9 foreign key (application_id) references application;
alter table if exists evaluation add constraint FK2j31vix2rfpkfkl4tq5gbrvd9 foreign key (professor_id) references professor;
alter table if exists professor add constraint FK3d3bqgq0xxp7nbeclk2a6vthc foreign key (id) references users;
